int mana = 75;
if (mana >= 100) {
    System.out.println("Ultimate spell!");
} else if (mana >= 50) {
    System.out.println("Standard spell");
} else {
    System.out.println("Rest — out of mana");
}

String element = "Fire";
int damage = switch (element) {
    case "Fire"  -> 100;
    case "Water" -> 80;
    case "Earth" -> 60;
    default      -> 40;
};
System.out.println("Damage: " + damage);

for (int i = 1; i <= 5; i++) {
    System.out.println("Fireball #" + i);
}

int mana = 100;
while (mana >= 20) {
    System.out.println("Cast! Mana: " + mana);
    mana -= 20;
}
System.out.println("Exhausted. Mana: " + mana);

int attempts = 0;
do {
    System.out.println("Attempt " + ++attempts);
} while (attempts < 3);
// Prints: Attempt 1, Attempt 2, Attempt 3

for (int i = 0; i < 10; i++) {
    if (i % 2 == 0) continue; // skip even numbers
    if (i > 7)     break;     // stop after 7
    System.out.println(i); // prints 1, 3, 5, 7
}

